//! Shared machinery for the F4 and F5 Gröbner basis engines.
//!
//! Both engines compute the same object — the reduced Gröbner basis of the
//! ideal generated by a finite list of polynomials over `Q` — but they choose
//! which S-polynomials to reduce in opposite ways:
//!
//! * [`super::f4`] takes a whole degree of critical pairs at once, expands
//!   them into a Macaulay matrix together with every reducible monomial, and
//!   eliminates the matrix over `Q`;
//! * [`super::f5`] orders the pairs by the signature of their S-polynomial and
//!   discards the ones a smaller signature already covers.
//!
//! This module holds what they share:
//!
//! * monomial arithmetic on exponent vectors (`divides`, `lcm`, `multiply`,
//!   `difference`, `total_degree`);
//! * sparse polynomial helpers on [`GPoly`] — scaling, multiplication by a
//!   monomial, S-polynomials, homogenisation;
//! * the sparse row echelon form used by the matrices;
//! * [`reduced_basis`], the final normalisation to the *reduced* basis.
//!
//! The reduced basis is unique for a given ideal and monomial order, so both
//! engines return literally the same list as
//! [`crate::rules::poly::groebner::groebner`]; [`reduced_basis`] follows the
//! same minimal-then-interreduce procedure as that reference implementation.
//!
//! Everything here is exact: coefficients are [`BigRational`], the echelon
//! form divides by its pivot and never by a floating point approximation, and
//! no decision depends on a numerical tolerance.

// The helpers are the pieces of two self-contained algorithms; a helper used
// by only one of them is still part of this shared vocabulary, and the
// matrix builder is one long, linear sequence of phases.
#![allow(
    clippy::single_call_fn,
    clippy::too_many_lines,
    clippy::too_many_arguments
)]

use std::cmp::Ordering;
use std::collections::BTreeMap;
use std::collections::HashMap;

use num_rational::BigRational;
use num_traits::One;
use num_traits::Zero;

use crate::graph::Cx;
use crate::graph::Graph;
use crate::graph::NodeId;
use crate::graph::Outcome;
use crate::graph::op::core;
use crate::rules::poly::groebner::GPoly;
use crate::rules::poly::groebner::Order;
use crate::rules::poly::groebner::reduce as normal_form;
use crate::rules::poly::repr::Gens;
use crate::rules::poly::to_groebner;

/// Exponent vector of a monomial over a fixed list of variables.
pub type Mono = Vec<u32>;

/// A sparse row of a Macaulay matrix: `(column rank, coefficient)` pairs,
/// sorted by increasing column rank. The last entry is the leading term,
/// because column ranks grow with the monomial order.
pub type Row = Vec<(usize, BigRational)>;

/// Whether the monomial `a` divides the monomial `b`.
pub fn divides(
    a: &[u32],
    b: &[u32],
) -> bool {
    a.iter().zip(b).all(|(x, y)| x <= y)
}

/// The least common multiple of two monomials.
#[must_use]
pub fn lcm(
    a: &[u32],
    b: &[u32],
) -> Mono {
    a.iter().zip(b).map(|(&x, &y)| x.max(y)).collect()
}

/// Whether two monomials are coprime, i.e. their lcm is their product. Equal
/// leading monomials are not coprime.
#[must_use]
pub fn coprime(
    a: &[u32],
    b: &[u32],
) -> bool {
    a.iter().zip(b).all(|(&x, &y)| x == 0 || y == 0)
}

/// The product of two monomials.
#[must_use]
pub fn multiply(
    a: &[u32],
    b: &[u32],
) -> Mono {
    a.iter()
        .zip(b)
        .map(|(&x, &y)| x.saturating_add(y))
        .collect()
}

/// The quotient `a / b`. Saturating, so it is only used when `b` divides `a`;
/// an invalid call yields zero exponents instead of a panic.
#[must_use]
pub fn difference(
    a: &[u32],
    b: &[u32],
) -> Mono {
    a.iter()
        .zip(b)
        .map(|(&x, &y)| x.saturating_sub(y))
        .collect()
}

/// The total degree of a monomial.
#[must_use]
pub fn total_degree(m: &[u32]) -> u64 {
    m.iter().map(|&e| u64::from(e)).sum()
}

/// `(a, b)` with `a <= b`, the canonical form of a pair of indices.
#[must_use]
pub const fn ordered(
    a: usize,
    b: usize,
) -> (usize, usize) {
    if a < b { (a, b) } else { (b, a) }
}

/// Whether every term of `p` has the same total degree.
#[must_use]
pub fn is_homogeneous(p: &GPoly) -> bool {
    let mut degrees = p.terms().iter().map(|(m, _)| total_degree(m));
    let Some(first) = degrees.next() else {
        return true;
    };
    degrees.all(|d| d == first)
}

/// `p` scaled so that its leading coefficient is one.
#[must_use]
pub fn monic(
    p: &GPoly,
    order: Order,
) -> GPoly {
    match p.leading() {
        | Some((_, lead)) => GPoly::new(
            p.terms()
                .iter()
                .map(|(m, c)| (m.clone(), c / lead))
                .collect(),
            order,
        ),
        | None => GPoly::new(Vec::new(), order),
    }
}

/// `p` multiplied by the scalar `factor`.
#[must_use]
pub fn scaled(
    p: &GPoly,
    factor: &BigRational,
    order: Order,
) -> GPoly {
    GPoly::new(
        p.terms()
            .iter()
            .map(|(m, c)| (m.clone(), c * factor))
            .collect(),
        order,
    )
}

/// `p` multiplied by the monomial `m`.
#[must_use]
pub fn times_monomial(
    p: &GPoly,
    m: &[u32],
    order: Order,
) -> GPoly {
    GPoly::new(
        p.terms()
            .iter()
            .map(|(mono, c)| (multiply(mono, m), c.clone()))
            .collect(),
        order,
    )
}

/// `a - b`.
#[must_use]
pub fn subtract(
    a: &GPoly,
    b: &GPoly,
    order: Order,
) -> GPoly {
    let mut terms = a.terms().to_vec();
    terms.extend(b.terms().iter().map(|(m, c)| (m.clone(), -c)));
    GPoly::new(terms, order)
}

/// The S-polynomial of two non-zero polynomials, with monic leading terms:
/// `(1/lc f) (L/lm f) f - (1/lc g) (L/lm g) g`, where `L = lcm(lm f, lm g)`.
#[must_use]
pub fn s_polynomial(
    f: &GPoly,
    g: &GPoly,
    order: Order,
) -> GPoly {
    let (Some((fm, fc)), Some((gm, gc))) = (f.leading(), g.leading()) else {
        return GPoly::new(Vec::new(), order);
    };
    let common = lcm(fm, gm);
    let left = times_monomial(f, &difference(&common, fm), order);
    let right = times_monomial(g, &difference(&common, gm), order);
    let left = scaled(&left, &(BigRational::one() / fc), order);
    let right = scaled(&right, &(BigRational::one() / gc), order);
    subtract(&left, &right, order)
}

/// `p` homogenised by a fresh variable appended after the existing ones.
///
/// Every term is multiplied by the power of the new variable that brings it
/// to the total degree of `p`. The new variable is the last one, which is the
/// smallest in the graded reverse-lexicographic order, so dehomogenising a
/// graded reverse-lexicographic basis gives a basis in the same order on the
/// original variables.
#[must_use]
pub fn homogenise(
    p: &GPoly,
    order: Order,
) -> GPoly {
    let degree = p.terms().iter().map(|(m, _)| total_degree(m)).max();
    let Some(degree) = degree else {
        return GPoly::new(Vec::new(), order);
    };
    GPoly::new(
        p.terms()
            .iter()
            .map(|(m, c)| {
                let mut exponent = m.clone();
                exponent.push(
                    u32::try_from(degree.saturating_sub(total_degree(m))).unwrap_or(u32::MAX),
                );
                (exponent, c.clone())
            })
            .collect(),
        order,
    )
}

/// `p` with the fresh homogenising variable set to one (its exponent
/// dropped).
#[must_use]
pub fn dehomogenise(
    p: &GPoly,
    order: Order,
) -> GPoly {
    GPoly::new(
        p.terms()
            .iter()
            .filter_map(|(m, c)| {
                let (_, rest) = m.split_last()?;
                Some((rest.to_vec(), c.clone()))
            })
            .collect(),
        order,
    )
}

/// The monomial order named by the optional third argument of
/// `groebner_f4(polys, vars[, order])`, mirroring `groebner`.
#[must_use]
pub fn order_of(
    graph: &Graph,
    args: &[NodeId],
) -> Option<Order> {
    match args {
        | [_, _] => Some(Order::Lex),
        | [_, _, order] => match graph.interner().symbol_name(graph.symbol_of(*order)?) {
            | "lex" => Some(Order::Lex),
            | "grlex" => Some(Order::GradedLex),
            | "grevlex" => Some(Order::GradedRevLex),
            | _ => None,
        },
        | _ => None,
    }
}

/// Reads the generators and the order out of a `groebner_f4`/`groebner_f5`
/// request node. `None` when the arguments are malformed or a polynomial
/// involves anything but the listed variables.
pub fn prepare_data(
    cx: &mut Cx<'_>,
    node: NodeId,
) -> Option<(Vec<GPoly>, Order, Gens)> {
    let args = cx.graph.children(node).to_vec();
    let order = order_of(cx.graph, &args)?;
    let polys = *args.first()?;
    let vars = *args.get(1)?;
    to_groebner(cx.graph, polys, vars, order).map(|(generators, gens)| (generators, order, gens))
}

/// The `list(p1, ...)` answer of a Gröbner basis request.
#[must_use]
pub fn list_node(
    graph: &mut Graph,
    basis: &[GPoly],
    gens: &Gens,
) -> NodeId {
    let terms: Vec<NodeId> = basis
        .iter()
        .map(|g| crate::rules::poly::from_groebner(graph, gens, g))
        .collect();
    graph.node(core::LIST, &terms)
}

/// The pinned answer of a Gröbner basis request.
#[must_use]
pub fn pinned(
    graph: &mut Graph,
    basis: &[GPoly],
    gens: &Gens,
) -> Outcome {
    Outcome::Pinned(list_node(graph, basis, gens))
}

/// The second phase shared by both engines: rewraps the basis computed by the
/// [`PreparedWork`](crate::graph::PreparedWork) into a list term.
pub fn commit(
    cx: &mut Cx<'_>,
    result: Box<dyn std::any::Any + Send>,
) -> Outcome {
    let Ok(result) = result.downcast::<(Option<Vec<GPoly>>, Gens)>() else {
        return Outcome::Pass;
    };
    let (basis, gens) = *result;
    let Some(basis) = basis else {
        return Outcome::Pass;
    };
    pinned(cx.graph, &basis, &gens)
}

/// The *reduced* Gröbner basis of the ideal generated by `basis`, assuming
/// `basis` already generates a Gröbner basis of that ideal.
///
/// Mirrors the final phase of [`crate::rules::poly::groebner::groebner`]: drop
/// every element whose leading monomial is divisible by another's, reduce
/// each survivor modulo the others, make it monic, and sort by increasing
/// leading monomial. The result is the unique reduced basis for the order.
#[must_use]
pub fn reduced_basis(
    basis: &[GPoly],
    order: Order,
) -> Vec<GPoly> {
    let mut minimal: Vec<GPoly> = Vec::new();
    for (index, g) in basis.iter().enumerate() {
        let Some((lead, _)) = g.leading() else {
            continue;
        };
        let redundant = basis.iter().enumerate().any(|(other, h)| {
            other != index
                && h.leading()
                    .is_some_and(|(m, _)| divides(m, lead) && (m != lead || other < index))
        });
        if !redundant {
            minimal.push(g.clone());
        }
    }
    let mut reduced: Vec<GPoly> = Vec::with_capacity(minimal.len());
    for (index, g) in minimal.iter().enumerate() {
        let others: Vec<GPoly> = minimal
            .iter()
            .enumerate()
            .filter(|&(k, _)| k != index)
            .map(|(_, h)| h.clone())
            .collect();
        reduced.push(monic(&normal_form(g, &others, order), order));
    }
    reduced.sort_by(|a, b| match (a.leading(), b.leading()) {
        | (Some((x, _)), Some((y, _))) => order.cmp(x, y),
        | _ => Ordering::Equal,
    });
    reduced
}

/// The column layout of one Macaulay matrix: the monomials in increasing
/// order, so that a larger column rank is a larger monomial.
pub struct Columns {
    /// The monomial of each column, ascending in the monomial order.
    monomials: Vec<Mono>,
    /// Column rank of each monomial.
    ranks: HashMap<Mono, usize>,
}

impl Columns {
    /// Numbers the distinct monomials ascending in `order`.
    #[must_use]
    pub fn new(
        mut monomials: Vec<Mono>,
        order: Order,
    ) -> Self {
        monomials.sort_by(|a, b| order.cmp(a, b));
        monomials.dedup();
        let ranks = monomials
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, m)| (m, i))
            .collect();
        Self { monomials, ranks }
    }

    /// The rank of a monomial, if it is a column.
    #[must_use]
    pub fn rank(
        &self,
        m: &[u32],
    ) -> Option<usize> {
        self.ranks.get(m).copied()
    }

    /// The monomial of a column.
    #[must_use]
    pub fn monomial(
        &self,
        rank: usize,
    ) -> Option<&Mono> {
        self.monomials.get(rank)
    }

    /// The number of columns.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.monomials.len()
    }
}

/// The row `x^shift * p` of a Macaulay matrix over `columns`.
pub fn matrix_row(
    p: &GPoly,
    shift: &[u32],
    columns: &Columns,
) -> Option<Row> {
    let mut row: Row = Vec::with_capacity(p.terms().len());
    for (mono, c) in p.terms() {
        row.push((columns.rank(&multiply(mono, shift))?, c.clone()));
    }
    row.sort_by_key(|(rank, _)| *rank);
    Some(row)
}

/// `a - factor * b` on rows sorted by increasing column rank.
fn subtract_rows(
    a: &Row,
    b: &Row,
    factor: &BigRational,
) -> Row {
    let mut out: Row = Vec::with_capacity(a.len().saturating_add(b.len()));
    let mut i = 0_usize;
    let mut j = 0_usize;
    loop {
        match (a.get(i), b.get(j)) {
            | (Some((ra, ca)), Some((rb, cb))) => match ra.cmp(rb) {
                | Ordering::Less => {
                    out.push((*ra, ca.clone()));
                    i = i.saturating_add(1);
                },
                | Ordering::Greater => {
                    out.push((*rb, -(cb * factor)));
                    j = j.saturating_add(1);
                },
                | Ordering::Equal => {
                    let value = ca - factor * cb;
                    if !value.is_zero() {
                        out.push((*ra, value));
                    }
                    i = i.saturating_add(1);
                    j = j.saturating_add(1);
                },
            },
            | (Some((ra, ca)), None) => {
                out.push((*ra, ca.clone()));
                i = i.saturating_add(1);
            },
            | (None, Some((rb, cb))) => {
                out.push((*rb, -(cb * factor)));
                j = j.saturating_add(1);
            },
            | (None, None) => return out,
        }
    }
}

/// The row echelon form of a list of rows, over `Q`.
///
/// Rows are taken in the given order and reduced against the pivots already
/// found; a row whose leading column has no pivot yet becomes a pivot, scaled
/// so that its pivot entry is one. The returned rows are the pivots, as
/// `(column rank of the leading entry, row)`, in increasing leading rank.
///
/// The computation is plain Gaussian elimination over the rationals: every
/// step subtracts an exact multiple of a pivot row, so the row space — and
/// with it the ideal generated by the rows read back as polynomials — is
/// exactly preserved. `steps` counts the row subtractions; `None` is returned
/// as soon as they exceed `limit`, so a runaway matrix cannot hang a caller.
pub fn echelon(
    rows: Vec<Row>,
    steps: &mut usize,
    limit: usize,
) -> Option<Vec<(usize, Row)>> {
    let mut pivots: BTreeMap<usize, Row> = BTreeMap::new();
    for row in rows {
        let mut current = row;
        while let Some(&(lead, _)) = current.last() {
            match pivots.get(&lead) {
                | Some(pivot) => {
                    *steps = steps.saturating_add(1);
                    if *steps > limit {
                        return None;
                    }
                    let Some((_, coefficient)) = current.last() else {
                        break;
                    };
                    let factor = coefficient.clone();
                    current = subtract_rows(&current, pivot, &factor);
                },
                | None => {
                    let Some((_, coefficient)) = current.last() else {
                        break;
                    };
                    let inverse = coefficient.recip();
                    for (_, value) in &mut current {
                        *value *= &inverse;
                    }
                    pivots.insert(lead, current);
                    break;
                },
            }
        }
    }
    Some(pivots.into_iter().collect())
}

/// The polynomial a row of a Macaulay matrix stands for.
#[must_use]
pub fn row_polynomial(
    row: &Row,
    columns: &Columns,
    order: Order,
) -> GPoly {
    GPoly::new(
        row.iter()
            .filter_map(|(rank, c)| columns.monomial(*rank).map(|m| (m.clone(), c.clone())))
            .collect(),
        order,
    )
}

#[cfg(test)]
mod tests {
    use num_bigint::BigInt;

    use super::*;

    fn q(n: i64) -> BigRational {
        BigRational::from_integer(BigInt::from(n))
    }

    fn poly(
        terms: &[(i64, [u32; 3])],
        order: Order,
    ) -> GPoly {
        GPoly::new(
            terms.iter().map(|(c, e)| (e.to_vec(), q(*c))).collect(),
            order,
        )
    }

    #[test]
    fn monomial_arithmetic() {
        assert!(divides(&[1, 0], &[2, 0]));
        assert!(!divides(&[0, 1], &[2, 0]));
        assert_eq!(lcm(&[2, 1], &[1, 3]), vec![2, 3]);
        assert_eq!(multiply(&[1, 2], &[3, 0]), vec![4, 2]);
        assert_eq!(difference(&[3, 2], &[1, 2]), vec![2, 0]);
        assert!(coprime(&[3, 0], &[0, 2]));
        assert!(!coprime(&[3, 1], &[0, 2]));
        assert_eq!(total_degree(&[1, 2, 3]), 6);
    }

    #[test]
    fn s_polynomial_cancels_the_common_leading_term() {
        let order = Order::GradedRevLex;
        // x^2 - y and x*y - 1: S = y*(x^2 - y) - x*(x*y - 1) = x - y^2, and
        // in graded reverse-lex y^2 > x, so y^2 is the leading term.
        let f = poly(&[(1, [2, 0, 0]), (-1, [0, 1, 0])], order);
        let g = poly(&[(1, [1, 1, 0]), (-1, [0, 0, 0])], order);
        let s = s_polynomial(&f, &g, order);
        assert_eq!(s.terms(), &[(vec![0, 2, 0], q(-1)), (vec![1, 0, 0], q(1))]);
        assert!(s_polynomial(&f, &GPoly::new(Vec::new(), order), order).is_zero());
    }

    #[test]
    fn the_echelon_form_keeps_the_row_space() {
        // The rows span a three-dimensional space: row 0 minus half of row 1
        // is e0, row 2 minus row 0 is -e1, hence e2, and the last row is a
        // multiple of the first.
        let rows = vec![
            vec![(0, q(1)), (1, q(1)), (2, q(1))],
            vec![(1, q(2)), (2, q(2))],
            vec![(0, q(1)), (2, q(1))],
            vec![(0, q(2)), (1, q(2)), (2, q(2))],
        ];
        let mut steps = 0;
        let pivots = echelon(rows, &mut steps, 10_000).unwrap_or_default();
        assert_eq!(pivots.len(), 3);
        // Every pivot has a unit leading entry.
        for (lead, row) in &pivots {
            assert_eq!(row.last(), Some(&(*lead, q(1))));
        }
        assert!(steps > 0);
        // A budget of zero steps reports exhaustion instead of looping.
        let one = vec![vec![(0, q(1)), (1, q(1))], vec![(0, q(1)), (1, q(2))]];
        assert!(echelon(one.clone(), &mut 0, 0).is_none());
        assert!(echelon(one, &mut 0, 100).is_some());
    }

    #[test]
    fn homogenisation_round_trips() {
        let order = Order::GradedRevLex;
        // x^2 + y + 1 homogenised by t: x^2 + y*t + t^2.
        let p = poly(&[(1, [2, 0, 0]), (1, [0, 1, 0]), (1, [0, 0, 0])], order);
        assert!(!is_homogeneous(&p));
        let h = homogenise(&p, order);
        assert!(is_homogeneous(&h));
        assert_eq!(
            h.terms(),
            &[
                (vec![2, 0, 0, 0], q(1)),
                (vec![0, 1, 0, 1], q(1)),
                (vec![0, 0, 0, 2], q(1)),
            ]
        );
        assert_eq!(dehomogenise(&h, order), p);
    }

    #[test]
    fn the_reduced_basis_is_monic_and_interreduced() {
        let order = Order::GradedRevLex;
        // <x^2, x*y, y^2> reduced is {x^2, x*y, y^2} with explicit rows.
        let basis = vec![
            poly(&[(2, [2, 0, 0])], order),
            poly(&[(4, [1, 1, 0])], order),
            poly(&[(1, [0, 2, 0]), (1, [1, 0, 0])], order),
        ];
        // x^2, x*y, y^2 + x is not a Gröbner basis; reducing the last by the
        // first two changes nothing, but the result must at least be monic.
        let reduced = reduced_basis(&basis, order);
        for g in &reduced {
            assert_eq!(g.leading().map(|(_, c)| c), Some(&q(1)));
        }
        let empty: Vec<GPoly> = Vec::new();
        assert!(reduced_basis(&empty, order).is_empty());
    }
}
